/* Chikoria Realm — cross-origin isolation shim for static hosts (GitHub Pages).
   One file, two roles: in a window it registers itself as a service worker and
   reloads once; as the service worker it re-serves every response with the
   COOP/COEP headers that SharedArrayBuffer (Godot threads) requires.
   File reassembly of the chunked .pck/.wasm happens in the page (index.html),
   not here — that avoids the SW-control race on first load. */
if (typeof window === 'undefined') {
	self.addEventListener('install', function () { self.skipWaiting(); });
	self.addEventListener('activate', function (e) { e.waitUntil(self.clients.claim()); });
	self.addEventListener('fetch', function (e) {
		var req = e.request;
		if (req.cache === 'only-if-cached' && req.mode !== 'same-origin') { return; }
		e.respondWith(fetch(req).then(function (res) {
			if (res.status === 0) { return res; }
			var h = new Headers(res.headers);
			h.set('Cross-Origin-Opener-Policy', 'same-origin');
			h.set('Cross-Origin-Embedder-Policy', 'require-corp');
			h.set('Cross-Origin-Resource-Policy', 'cross-origin');
			return new Response(res.body, { status: res.status, statusText: res.statusText, headers: h });
		}));
	});
} else {
	(function () {
		if (window.crossOriginIsolated || !('serviceWorker' in navigator)) { return; }
		var src = document.currentScript && document.currentScript.src;
		if (!src) { return; }
		navigator.serviceWorker.register(src).then(function (reg) {
			// first install: reload once so the worker starts intercepting this page
			if (reg.active && !navigator.serviceWorker.controller) { window.location.reload(); return; }
			reg.addEventListener('updatefound', function () {
				var w = reg.installing;
				if (!w) { return; }
				w.addEventListener('statechange', function () {
					if (w.state === 'activated' && !navigator.serviceWorker.controller) { window.location.reload(); }
				});
			});
		}).catch(function (e) { console.error('coi-serviceworker registration failed:', e); });
	}());
}
